// Manifest for T10b. Static. Commands 01-02 are hashed in full.
// Command 03 is this process. Its out, err, and exit are sealed next.
// Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';

function fileRec(name) {
  const data = readFileSync(resolve(name));
  return { path: name.replaceAll('\\', '/'), sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}
function walk(dir, acc) {
  for (const name of readdirSync(dir)) {
    const abs = join(dir, name);
    if (statSync(abs).isDirectory()) walk(abs, acc);
    else acc.push(relative(resolve('.'), abs).replaceAll('\\', '/'));
  }
}
function commandRec(n, full) {
  const nn = String(n).padStart(2, '0');
  const cmdText = readFileSync(resolve('work/out/cmd/' + nn + '.cmd.txt'), 'utf8');
  const files = { cmd: fileRec('work/out/cmd/' + nn + '.cmd.txt') };
  let status = null;
  let scripts = null;
  let wrapper = null;
  if (full) {
    const exitDoc = JSON.parse(readFileSync(resolve('work/out/cmd/' + nn + '.exit'), 'utf8'));
    status = exitDoc.status;
    scripts = exitDoc.scripts || [];
    wrapper = exitDoc.wrapper_sha256;
    files.out = fileRec('work/out/cmd/' + nn + '.out');
    files.err = fileRec('work/out/cmd/' + nn + '.err');
    files.exit = fileRec('work/out/cmd/' + nn + '.exit');
  }
  return {
    n,
    requested: (cmdText.match(/^requested: (.*)$/m) || [])[1] || '',
    status,
    wrapper_sha256: wrapper,
    scripts,
    files,
  };
}
function importsOf(path) {
  const text = readFileSync(resolve(path), 'utf8');
  const specifiers = [];
  const re = /import\s+[\s\S]*?\sfrom\s+['"]([^'"]+)['"]/g;
  for (const match of text.matchAll(re)) specifiers.push(match[1]);
  return { script: path.replaceAll('\\', '/'), specifiers };
}

const inputs = [
  'brief.md',
  'TASK.md',
  'review-brief.md',
  'templates/result.md',
  'inputs/00_0100_50000020.decoded.bin',
  'inputs/02_0106_458c0020.decoded.bin',
  'ref/tasks/T10-afon-profile-storage-5b82/decision.md',
  'ref/tasks/T10-afon-profile-storage-5b82/run-20261119-173646-review/review.md',
  'ref/tasks/T10-afon-profile-storage-5b82/run-20261119-163743/work/out/encoding.md',
  'ref/tasks/T10-afon-profile-storage-5b82/run-20261119-163743/work/scripts/codec.mjs',
  'ref/tasks/T10-afon-profile-storage-5b82/run-20261119-163743/work/scripts/codec_test_t10c.mjs',
  'ref/tasks/T10-afon-profile-storage-5b82/run-20261119-163743/work/out/ranges-t10c.json',
  'ref/tasks/T3l-afon-editor-completion/run-20261119-083228/work/out/design.md',
  'ref/tasks/T3l-afon-editor-completion/run-20261119-083228/work/out/profile-layout.md',
  'ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/out/profile-layout.md',
  'ref/tasks/T8c-afon-bank-and-init-reconcile/brief.md',
  'ref/tasks/T8c-afon-bank-and-init-reconcile/run-20261119-163743/work/result.md',
  'ref/tasks/T8c-afon-bank-and-init-reconcile/run-20261119-163743/work/out/q2b-summary.json',
  'ref/tasks/T8c-afon-bank-and-init-reconcile/run-20261119-163743/work/scripts/hook_t8c2.mjs',
];
for (const path of inputs) if (!existsSync(resolve(path))) throw new Error('missing input ' + path);

const outputPaths = [];
walk(resolve('work/out'), outputPaths);
outputPaths.sort();
const outputs = ['work/result.md', ...outputPaths].map(fileRec);
const scriptPaths = [];
walk(resolve('work/scripts'), scriptPaths);
scriptPaths.sort();
const sources = scriptPaths.map(fileRec);
const imports = scriptPaths.map(importsOf);

const commands = [];
for (let n = 1; n <= 2; n++) commands.push(commandRec(n, true));
commands.push(commandRec(3, false));

let pythonVersion = '';
try {
  pythonVersion = execFileSync('python', ['-I', '-c', 'import sys; print(sys.version)'], { encoding: 'utf8' }).trim();
} catch (err) {
  pythonVersion = String(err);
}

const doc = {
  task: 'T10b-afon-profile-codec-domain',
  brief_sha256: fileRec('brief.md').sha256,
  emulator_modules: [],
  experiment_versions: 0,
  note: 'Static codec domain and pose-keyed layout. No emulator process and no OM-Emu import. Commands 01-02 are hashed in full. Command 03 is this manifest; its out, err, and exit are in the external seal. Command 04 writes that seal. Built-in Node modules have no workspace file.',
  imports,
  inputs: inputs.map(fileRec),
  sources,
  outputs,
  commands,
  tool_versions: {
    node: process.version,
    python: pythonVersion,
  },
};
writeFileSync(resolve('work/evidence-manifest.json'), JSON.stringify(doc, null, 2) + '\n');
process.stdout.write(JSON.stringify({
  ok: true,
  inputs: doc.inputs.length,
  sources: sources.length,
  outputs: outputs.length,
  commands: commands.length,
  imports: imports.length,
  brief_sha256: doc.brief_sha256,
}) + '\n');
